Definition supp_xor {n}
  (S T : Mask n -> Prop) : Mask n -> Prop :=
  fun U => exists A B, S A /\ T B /\ mask_xor A B = U.

Record ExcNum := {
  exc_grade : nat;
  exc_l1    : Q;
}.

Definition exc_of {n} (sq : Vector.t Q n) (e : GA_expr n) : ExcNum :=
  {| exc_grade := max_grade_during sq e;
     exc_l1    := max_l1_during sq e |}.

Record EasyCompiler := {
  R : nat -> Type;

  target : forall {n : nat}, R n -> Corner n -> bool;
  compile : forall {n : nat}, R n -> GA_expr n;

  B : nat -> ExcNum;
  d0 : Q;

  compile_correct :
    forall {n : nat} (sq : Vector.t Q n) (r : R n),
      computes sq (compile (n:=n) r) (target (n:=n) r);

  compile_exc_bound :
    forall {n : nat} (sq : Vector.t Q n) (r : R n),
      exc_pre (exc_of sq (compile (n:=n) r)) (B (expr_size (compile (n:=n) r)));

  compile_boolish_bound :
    forall {n : nat} (sq : Vector.t Q n) (r : R n),
      trace_boolish_le sq (compile (n:=n) r) d0
}.

Definition and_gens {n}
  (gs1 gs2 : list (Corner n -> bool)) : list (Corner n -> bool) :=
  concat (map (fun g1 => map (and_gen g1) gs2) gs1).

Definition trace_boolish_exists_k {n}
        (sq : Vector.t Q n) (e : GA_expr n) (d : Q) : Prop :=
        exists k : nat, trace_boolish_k_le sq e k d.

Definition trace_boolish_poly_size {n}
  (sq : Vector.t Q n) (e : GA_expr n) (d : Q) : Prop :=
  exists k, (k <= Nat.pow (size_expr e) 3)%nat /\ trace_boolish_k_le sq e k d.

Definition trace_boolish_poly_n {n}
  (sq : Vector.t Q n) (e : GA_expr n) (d : Q) : Prop :=
  exists k, (k <= Nat.pow n 3)%nat /\ trace_boolish_k_le sq e k d.

Definition dag_exc (sq : Vector.t Q n) {k} (d : GA_dag k) : ExcNum :=
  {| exc_grade := dag_max_grade sq d;
     exc_l1    := dag_max_l1 sq d |}.

Definition dag_trace_boolish_exists_k (sq : Vector.t Q n) {k}
    (d : GA_dag k) (tol : Q) : Prop :=
  exists bound, dag_trace_boolish_k sq d bound tol.

Definition dag_trace_exact_bool (sq : Vector.t Q n) {k}
    (d : GA_dag k) : Prop :=
  dag_trace_boolish_k sq d 1 0.

Definition dag_computes (sq : Vector.t Q n) {k}
    (d : GA_dag k) (root : Fin.t k) (f : Corner n -> bool) : Prop :=
  forall m : Mask n, eval_dag sq d root m == embed f m.

Record DAG_EasyCompiler := {
  dag_R : nat -> Type;

  dag_target : forall {m : nat}, dag_R m -> Corner m -> bool;

  dag_compile_size : forall {m : nat}, dag_R m -> nat;
  dag_compile : forall {m : nat} (r : dag_R m),
    GA_dag m (S (dag_compile_size r));
  dag_compile_root : forall {m : nat} (r : dag_R m),
    Fin.t (S (dag_compile_size r));

  dag_B : nat -> ExcNum;
  dag_d0 : Q;

  dag_compile_correct :
    forall {m : nat} (sq : Vector.t Q m) (r : dag_R m),
      dag_computes m sq (dag_compile r) (dag_compile_root r)
                   (dag_target r);

  dag_compile_exc_bound :
    forall {m : nat} (sq : Vector.t Q m) (r : dag_R m),
      exc_pre (dag_exc m sq (dag_compile r))
              (dag_B (S (dag_compile_size r)));

  dag_compile_boolish_bound :
    forall {m : nat} (sq : Vector.t Q m) (r : dag_R m),
      dag_trace_boolish m sq (dag_compile r) dag_d0
}.

Lemma mv_gp_one_l :
  forall n (sq : Vector.t Q n) (F : MV n) (U : Mask n),
    @mv_gp n sq mv_one F U == F U.

Lemma mv_gp_one_r :
  forall n (sq : Vector.t Q n) (F : MV n) (U : Mask n),
    @mv_gp n sq F (@mv_one n) U == F U.

Lemma all_corners_2 :
  all_corners 2 = [Vector.cons _ Pos _ (Vector.cons _ Pos _ (Vector.nil _));
                   Vector.cons _ Pos _ (Vector.cons _ Neg _ (Vector.nil _));
                   Vector.cons _ Neg _ (Vector.cons _ Pos _ (Vector.nil _));
                   Vector.cons _ Neg _ (Vector.cons _ Neg _ (Vector.nil _))].
